const NAMES = {1:'Anonymous or fake team',2:'Unlocked liquidity',3:'Unaudited contract or fake audit',4:'Concentrated holdings',5:'Unrealistic yields',6:'No real development activity',7:'Fake partnerships',8:'Hidden mint functions',9:'Brand-new protocol',10:'Low or fake TVL',11:'Opaque treasury',12:'Toxic community and fake urgency'};
const rows = $input.all().map(i => i.json).filter(r => r['Score'] !== undefined && r['Score'] !== '');
const parse = s => { const d = new Date(String(s).replace(',', '')); return isNaN(d) ? null : d; };
const cutoff = Date.now() - 7 * 24 * 3600 * 1000;
const week = rows.filter(r => { const d = parse(r['Received']); return d && d.getTime() >= cutoff; });

function stats(list) {
  const n = list.length;
  if (!n) return null;
  const num = k => list.map(r => Number(r[k]) || 0);
  const avg = a => a.reduce((x, y) => x + y, 0) / a.length;
  const secs = num('Seconds').sort((a, b) => a - b);
  const median = secs.length % 2 ? secs[(secs.length - 1) / 2] : (secs[secs.length / 2 - 1] + secs[secs.length / 2]) / 2;
  const found = num('Flags found');
  const fa = num('False alarms');
  const misses = {};
  for (let f = 1; f <= 12; f++) misses[f] = 0;
  for (const r of list) String(r['Missed flags'] || '').split(',').filter(Boolean).forEach(f => { if (misses[f] !== undefined) misses[f]++; });
  const top = Object.entries(misses).filter(([, c]) => c > 0).sort((a, b) => b[1] - a[1]).slice(0, 3)
    .map(([f, c]) => `#${f} ${NAMES[f]}: missed by ${Math.round(c / n * 100)}% (${c} of ${n})`);
  return {
    n,
    avgFound: avg(found).toFixed(1),
    avgScore: Math.round(avg(num('Score'))),
    avgFalse: avg(fa).toFixed(1),
    medianSecs: Math.round(median),
    all12: found.filter(x => x === 12).length,
    perfect: list.filter(r => Number(r['Flags found']) === 12 && Number(r['False alarms']) === 0).length,
    top
  };
}

const fmt = s => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
const block = (title, s) => !s ? `${title}\nNo games finished.` : [
  title,
  `Games finished: ${s.n}`,
  `Average flags found: ${s.avgFound} of 12`,
  `Average score: ${s.avgScore}`,
  `Average false alarms: ${s.avgFalse}`,
  `Median time: ${fmt(s.medianSecs)}`,
  `Found all 12: ${s.all12} (${Math.round(s.all12 / s.n * 100)}%)`,
  `Perfect games (12 found, 0 false alarms): ${s.perfect}`,
  s.top.length ? `Most missed:\n  ${s.top.join('\n  ')}` : 'Most missed: none, everyone caught everything'
].join('\n');

const w = stats(week), a = stats(rows);
const subject = w ? `Spot the Flag weekly: ${w.n} games, ${w.avgFound}/12 average` : 'Spot the Flag weekly: no games this week';
const body = [
  block('LAST 7 DAYS', w),
  '',
  block('ALL TIME', a),
  '',
  'Full data: https://docs.google.com/spreadsheets/d/YOUR_GOOGLE_SHEET_ID/edit',
  'Site: https://12redflags.com'
].join('\n');
return [{ json: { subject, body } }];
